    SELECT 'Espino morisco', 'Rhamnus oleoides', 'flora', NULL, NULL, 'No catalogada', NULL, NULL, NULL, 'Septiembre, octubre, noviembre, enero, febrero, marzo, abril, mayo, junio, julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhamnus_oleoides.JPG?width=1280', 'User:Xemenendura (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 3, '{"origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 0, 0, 'Sin descripción: ninguna fuente publica texto para este taxón. Oculta hasta redactarla.', 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rhamnaceae', 'Rhamnus', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 7737, 7867604, NULL
