    SELECT 'Albaida', 'Anthyllis cytisoides', 'flora', 'Mata', 'Matorral seco y soleado sobre margas y suelos pobres', 'No catalogada', 'Mata de aspecto blanquecino por la fina pelusa que cubre hojas y tallos, un recurso frente al sol y la sequía. En primavera se llena de espigas de flores amarillas que atraen a muchos insectos. Es una de las leguminosas que primero coloniza laderas degradadas y taludes.', NULL, 'Aspecto grisáceo y aterciopelado al tacto; Flores amarillas pequeñas en espigas apretadas; Hojas divididas en tres, la del centro más larga', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Anthyllis_cytisoides.JPG?width=1280', 'Ximenex (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha, que la cita como «Anthillis cytisoides» (el §3.2.4.2.2 la nombra en la descripción de la vegetación (romeral y tomillar de solana), no en la Tabla 56: la norma afirma su presencia en el espacio, no le asigna categoría de protección. Errata del texto: se lee «Anthillis» por Anthyllis); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Anthyllis', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 2186, 5352466, NULL
    UNION ALL
    SELECT 'Probayernos', 'Anthyllis lagascana', 'flora', NULL, NULL, 'Interés especial', NULL, NULL, NULL, 'Febrero, marzo, abril, mayo, junio, julio, septiembre, octubre', NULL, NULL, NULL, NULL, 4, NULL, 4, '{"origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 1, 0, 'Sin descripción: ninguna fuente publica texto para este taxón. Oculta hasta redactarla.', 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha, con la categoría «De Interés Especial (Catálogo Regional de Flora Silvestre Protegida)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Anthyllis', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 2053, 5352349, NULL
