    SELECT 'Tablero de damas', 'Fritillaria lusitanica', 'flora', 'Planta bulbosa', 'Pastizales, claros de matorral y pedregales de montaña', 'Interés especial', 'Bulbosa de tallo fino y hojas estrechas que cuelga una o dos flores en forma de campana, con un jaspeado pardo y verdoso que recuerda a un tablero de ajedrez. Pasa desapercibida entre la hierba pese a su forma llamativa.', NULL, 'Flor colgante en campana con dibujo ajedrezado; Tallo fino con pocas hojas estrechas; Colores apagados que la camuflan en el pastizal', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fritillaria_lusitanica_2_2601.jpg?width=1280', 'Balles2601 (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Liliopsida', 'Liliales', 'Liliaceae', 'Fritillaria', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 4633, 5300414, NULL
