    SELECT 'Paloma bravía', 'Columba livia', 'fauna', 'Ave', NULL, 'LC', 'Ave compacta, de mediano tamaño, redondeada y de cabeza pequeña. Muestra una coloración dominante grisácea, con el obispillo blanco y dos bandas alares negras. Dado que se trata del ancestro silvestre de las palomas domésticas —con las que puede hibridarse—, presenta un aspecto muy similar a la forma “típica” de estas. Debido a la frecuente hibridación entre ambas variedades y a la presencia de muchas poblaciones cimarronas, resulta muy difícil distinguir cuándo una población es realmente silvestre o pertenece a la forma semidoméstica. Tiene un vuelo muy rápido y directo, con batidos potentes.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Wild_rock_dove_at_Raikot%2C_Diamer%2C_Gilgit-Baltistan%2C_Pakistan.png?width=1280', 'Birds of Gilgit-Baltistan from Aliabad, Hunza, Pakistan (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Columbiformes', 'Columbidae', 'Columba', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Presencia respaldada por 3 ocurrencias de GBIF dentro del espacio. Este espacio NO tiene ZEPA declarada, así que no hay lista oficial de aves del sitio Natura 2000 con la que contrastarla: el respaldo documental, cuando lo hay, es el inventario de fauna del plan de gestión del espacio.', 11608, 2495414, NULL
    UNION ALL
    SELECT 'Triguero', 'Emberiza calandra', 'fauna', 'Ave', 'Cultivos de secano, pastizales y llanos abiertos con posaderos', 'LC', 'Escribano grande y rechoncho, pardo y rayado, sin marcas llamativas. Canta desde un cable o una mata con una frase acelerada que suena como un manojo de llaves agitado, y vuela distancias cortas dejando las patas colgando.', NULL, 'Canto como un manojo de llaves agitándose; Vuela con las patas colgando, sin recogerlas; Aspecto pesado y pardo, sin marcas vistosas', 'Todo el año', 'https://inaturalist-open-data.s3.amazonaws.com/photos/606625336/original.jpg', 'euqirneto (CC BY 4.0) · GBIF', NULL, NULL, 2, '{"categoria":"protegida por la Directiva Aves 2009/147/CE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"protegida por la Directiva Aves 2009/147/CE","ambito":"estatal","origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Passeriformes', 'Emberizidae', 'Emberiza', 'LC', 'No incluida en el LESRPE; protegida por la Directiva Aves 2009/147/CE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Presencia respaldada por 3 ocurrencias de GBIF dentro del espacio. Este espacio NO tiene ZEPA declarada, así que no hay lista oficial de aves del sitio Natura 2000 con la que contrastarla: el respaldo documental, cuando lo hay, es el inventario de fauna del plan de gestión del espacio.', 10938, 7634625, NULL
