    SELECT 'Cogujada montesina', 'Galerida theklae', 'fauna', 'Ave', 'Matorral bajo, laderas pedregosas y eriales con vegetación rala', 'Protegida (LESRPE)', 'Cogujada de cresta puntiaguda, muy parecida a la común pero de pico más corto y grueso y con el pecho más nítidamente rayado. Prefiere el matorral y las laderas pedregosas, mientras que la común busca cultivos, caminos y bordes de pueblo.', NULL, 'Cresta alta y afilada, casi triangular; Pico más corto y romo que el de la cogujada común; Rayado del pecho bien definido, no difuminado', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Galerida_theklae_Madrid.jpg?width=1280', 'Adrian198cm (Public domain) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha, con la categoría «Anexo I de la Directiva Aves»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Alaudidae', 'Galerida', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Presencia respaldada por 3 ocurrencias de GBIF dentro del espacio. Este espacio NO tiene ZEPA declarada, así que no hay lista oficial de aves del sitio Natura 2000 con la que contrastarla: el respaldo documental, cuando lo hay, es el inventario de fauna del plan de gestión del espacio.', 12316, 9330514, NULL
    UNION ALL
    SELECT 'Urraca común', 'Pica pica', 'fauna', 'Ave', NULL, 'LC', 'Se trata de una de las más conocidas especies de la fauna española, circunstancia a la que contribuyen no solo su inconfundible aspecto, sino también unos hábitos poco recatados y su capacidad de instalarse en hábitats muy transformados, incluido el interior de las grandes ciudades. Especie de tamaño intermedio entre los córvidos, la urraca luce un llamativo y característico plumaje blanquinegro, que adquiere bellas irisaciones en diferentes zonas, sobre todo en las plumas caudales. Cuando se desplaza resulta también fácilmente identificable, además de por su diseño cromático, por poseer una silueta característica y un vuelo ondulante durante el cual bate espasmódicamente las alas.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Urraca_(Pica_pica)%2C_Almuradiel%2C_Ciudad_Real%2C_Espa%C3%B1a%2C_2021-12-19%2C_DD_04.jpg?width=1280', 'Diego Delso (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Passeriformes', 'Corvidae', 'Pica', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Presencia respaldada por 3 ocurrencias de GBIF dentro del espacio. Este espacio NO tiene ZEPA declarada, así que no hay lista oficial de aves del sitio Natura 2000 con la que contrastarla: el respaldo documental, cuando lo hay, es el inventario de fauna del plan de gestión del espacio.', 11981, 5229490, NULL
    UNION ALL
    SELECT 'Avión roquero', 'Ptyonoprogne rupestris', 'fauna', 'Ave', 'Acantilados mediterráneos con Limonium', 'Protegida (LESRPE)', 'Hirundínido pardo y robusto que vuela pegado a las paredes rocosas de acantilados y barrancos, donde construye su nido de barro.', NULL, 'Vuelo pegado a las paredes; Manchas claras en la cola; Nido de barro en cortados', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ptyonoprogne_rupestris_in_flight.jpg?width=1280', 'ferran pestaña (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen II §3.2.4.2 (BORM n.º 103, de 6 de mayo de 2025): la norma la enumera en el inventario de especies del propio Monumento Natural, que no solapa Red Natura 2000 y tiene por tanto el mismo perímetro que esta ficha, con la categoría «Parcialmente migradora (Directiva Aves)»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Hirundinidae', 'Ptyonoprogne', 'LC', 'LESRPE (RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Presencia respaldada por 3 ocurrencias de GBIF dentro del espacio. Este espacio NO tiene ZEPA declarada, así que no hay lista oficial de aves del sitio Natura 2000 con la que contrastarla: el respaldo documental, cuando lo hay, es el inventario de fauna del plan de gestión del espacio.', 12131, 4408796, NULL
